{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "신고 목록 조회 시간의 감소를 인덱스와 조인 수정의 효과로 판단할 수 있는 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 신고 목록 조회에 3.2초가 걸렸다.",
          "task": "조회 지연의 원인을 개선하고 실제 성능 향상을 확인해야 했다.",
          "action": "인덱스와 조인을 수정한 뒤 실행 양상과 조회 시간을 확인했다.",
          "result": "조회 시간이 0.4초로 줄어든 결과를 수정 내용과 연결해 설명한다."
        },
        "expectedEvidence": [
          "조회 시간 감소를 수정의 효과로 판단한 확인 근거를 제시한다.",
          "실행 계획에서 찾은 병목과 수정 후 달라진 점을 연결한다.",
          "개선 전후 조회 시간을 비교한 실제 조회 조건을 설명한다."
        ]
      },
      "question": "포켓마켓 인턴 때 인덱스와 조인을 손봐 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요. 조회 시간 감소가 이 수정의 효과인지는 무엇으로 확인하셨나요?",
      "answerTip": "당시 직접 확인한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "수정 전후의 실행 양상과 조회 시간을 근거로 성능 향상이 수정의 효과임을 설명한다.",
            "실제 비교한 조회 조건을 밝혀 3.2초에서 0.4초로 줄어든 수치의 의미를 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "수정 전후 조회 시간을 확인했다고 답하지만 병목 변화나 비교 조건에 대한 설명은 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "확인한 근거 없이 개선 수치만 반복하거나 인덱스의 일반적인 효과만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 찾은 중복 실행 원인에 대해 일시적인 중단보다 잠금을 선택한 복구와 재발 방지 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 배포 후 두 서버의 스케줄러가 같은 알림을 중복 발송했다.",
          "task": "중복 발송을 해소하고 같은 실행 충돌의 재발을 막아야 했다.",
          "action": "로그로 확인한 실행 충돌에 근거해 잠금 키를 적용했다.",
          "result": "잠금이 현재 오류의 해소와 같은 원인의 재발 방지에 적합한 이유를 설명한다."
        },
        "expectedEvidence": [
          "한 서버의 실행 중단 대신 잠금 키를 선택한 이유를 설명한다.",
          "시간순 로그에서 확인한 두 서버의 중복 실행을 선택 근거로 연결한다.",
          "일시적인 실행 중단과 잠금의 재발 방지 효과 차이를 설명한다."
        ]
      },
      "question": "포켓마켓 인턴 때 두 서버의 스케줄러 중복 실행을 잠금 키로 고치셨던데요. 한 서버의 실행을 끄는 대신 잠금을 택하신 이유는 무엇이었나요?",
      "answerTip": "당시 선택에 영향을 준 생각을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그에서 확인한 두 서버의 실행 충돌을 근거로 잠금 키를 선택한 이유를 구체적으로 설명한다.",
            "한 서버의 실행 중단과 비교해 잠금이 같은 원인의 재발을 막는 데 적합한 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "중복 실행 방지를 위해 잠금을 선택했다고 답하지만 로그 근거나 일시 중단과의 차이는 막연하다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금을 선택한 이유를 설명하지 못하거나 중복 실행 원인과 무관한 조치만 제시한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "세탁소 인터뷰에서 얻은 요청을 개발 팀원과 합의할 구현 범위로 옮긴 판단 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 다섯 곳의 인터뷰를 바탕으로 예약 서비스 요구사항을 작성한 과제였다.",
          "task": "인터뷰 요청 중 이번에 구현할 범위를 개발 담당 팀원과 정해야 했다.",
          "action": "요청이 해결하는 문제를 바탕으로 구현할 요구의 우선순위를 판단했다.",
          "result": "이번에 구현할 요구와 제외하거나 미룰 요구의 경계가 구체화되었다."
        },
        "expectedEvidence": [
          "인터뷰 요청을 구현 범위에 포함할지 결정한 근거를 설명한다.",
          "실제 요청 사례로 해결 목적과 범위 결정의 연결을 보여 준다."
        ]
      },
      "question": "세탁소 예약 서비스 과제에서 다섯 곳을 인터뷰해 개발 팀원과 범위를 조정하셨던데요. 인터뷰 요청을 이번 구현에 넣을지는 어떤 근거로 결정하셨나요?",
      "answerTip": "당시 실제로 판단한 사례를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 인터뷰 요청을 들어 구현 범위에 포함하거나 제외한 근거를 구체적으로 설명한다.",
            "요청이 해결하는 문제와 구현 우선순위의 관계가 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 정한 근거는 제시하지만 실제 요청과의 연결이 일반적인 설명에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "인터뷰나 문서 작성 사실만 반복하고 구현 범위를 결정한 근거를 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 별도 화면으로 구분할지 판단하고 화면의 상태와 흐름으로 구체화하는 능력을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 예약 서비스 과제에서 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "task": "예외 상황을 기존 화면의 상태로 표현할지 별도 화면으로 구분할지 정해야 했다.",
          "action": "예외 발생 후 사용자가 취할 행동과 화면 변화를 근거로 표현 방식을 결정했다.",
          "result": "예외 발생 시 표시할 화면과 다음 흐름을 구현자가 이해할 수 있게 정리했다."
        },
        "expectedEvidence": [
          "예외 상황을 별도 화면으로 나눌지 결정한 근거를 설명한다.",
          "실제 예외 사례의 화면 상태와 다음 흐름으로 판단을 뒷받침한다."
        ]
      },
      "question": "세탁소 예약 서비스 과제에서 예외 상황을 포함한 화면설계서 28장을 만드셨던데요. 예외 상황을 별도 화면으로 나눌지 결정한 근거는 무엇이었나요?",
      "answerTip": "직접 작성했던 사례를 떠올려 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 예외 사례를 들어 별도 화면이나 기존 화면의 상태로 표현한 판단 근거를 설명한다.",
            "예외 발생 후 화면 상태와 다음 흐름이 판단 근거에 일관되게 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면을 구분한 근거는 설명하지만 실제 예외 상황의 상태나 흐름과 연결이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "화면 수나 도구 사용법만 설명하고 예외 상황의 화면 표현을 결정한 근거를 제시하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "평소와 다른 용량의 처방을 그대로 수행하지 않고 담당의 확인을 우선한 판단 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원에서 수술 후 환자의 진통제가 평소 용량의 두 배로 처방되었다.",
          "task": "처방된 용량을 그대로 투약해도 되는지 판단해야 했다.",
          "action": "확인 없이 투약할 수 없다고 판단해 투약을 멈추고 담당의에게 확인했다.",
          "result": "담당의 확인을 통해 진통제 처방의 입력 오류를 발견했다."
        },
        "expectedEvidence": [
          "처방대로 투약하기보다 담당의 확인을 우선해야 했던 구체적 근거를 설명한다.",
          "투약을 보류하고 담당의에게 확인해 처방 오류를 확인한 행동을 제시한다."
        ]
      },
      "question": "푸른결종합병원에서 평소 두 배 용량의 진통제 투약을 멈추셨던데요. 처방대로 투약하기보다 담당의 확인이 먼저라고 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 실제로 판단한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소와 달랐다는 언급을 넘어, 당시 처방을 확인 없이 수행할 수 없었던 구체적 근거를 설명한다.",
            "그 근거에 따라 투약을 보류하고 담당의 확인으로 입력 오류를 확인한 행동이 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "두 배 용량이어서 확인을 우선했다고 답하지만, 당시 판단의 근거는 일반적인 안전 원칙에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "담당의 확인을 우선한 근거를 설명하지 못하거나, 처방이 있으면 확인 없이 투약한다는 답에 머문다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "교대 시간대의 낙상 사례를 바탕으로 다음 근무자에게 전달할 관찰 관련 정보를 정한 이유를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 사고 보고서에서 수술 후 첫 보행 환자의 낙상이 교대 시간대에 몰렸다.",
          "task": "다음 근무자가 환자 상태를 이어서 살필 수 있도록 인수인계 정보를 보완해야 했다.",
          "action": "진통제 투여 시각을 다음 근무자에게 전달해야 할 정보로 정해 체크리스트에 추가했다.",
          "result": "인수인계 체크리스트 보완 후 분기 낙상 건수가 5건에서 2건으로 줄었다."
        },
        "expectedEvidence": [
          "진통제 투여 시각이 다음 근무자의 환자 상태 관찰에 필요한 이유를 설명한다.",
          "교대 시간대의 낙상 사례와 해당 정보의 인계 필요성을 연결해 설명한다."
        ]
      },
      "question": "푸른결종합병원에서 낙상 인수인계표에 진통제 투여 시각을 추가하셨던데요. 왜 진통제 투여 시각을 다음 근무자가 알아야 한다고 판단하셨나요?",
      "answerTip": "당시 경험에서 떠오르는 구체적인 내용으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 투여 시각을 전달하는 것이 다음 근무자의 환자 상태 관찰에 어떤 의미가 있는지 구체적으로 설명한다.",
            "교대 시간대의 낙상 사례를 근거로 해당 정보를 인계해야 하는 이유를 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자 안전이나 관찰을 위해 필요하다고 답하지만, 낙상 사례와 투여 시각의 연결은 일반론에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "투여 시각을 다음 근무자에게 전달해야 하는 이유를 설명하지 못하거나 낙상 감소 수치만 반복한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "감속기 축에 걸리는 하중과 지지 조건을 근거로 축 지름을 결정한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "기계요소설계 개인 과제에서 주어진 하중으로 감속기 축 지름과 베어링을 선정했다.",
          "task": "주어진 조건에서 축 지름을 더 줄일 수 없는 이유를 설명해야 했다.",
          "action": "하중이 전달되는 경로와 축을 지지하는 조건을 바탕으로 필요한 축 지름을 판단했다.",
          "result": "선정한 축 지름의 필요성을 과제의 계산 결과와 연결해 설명할 수 있었다."
        },
        "expectedEvidence": [
          "선정한 축 지름을 더 줄이지 않은 결정적인 이유를 설명한다.",
          "과제의 하중과 지지 조건을 축 지름 선정 계산에 연결한다."
        ]
      },
      "question": "기계요소설계 수업에서 주어진 하중으로 감속기 축 지름과 베어링을 정하셨던데요. 축 지름을 더 줄이지 않은 이유는 무엇이었나요?",
      "answerTip": "당시 실제로 판단한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
